"""Seal the read-only handoff audit and rejected shell patch evidence."""
import json,shutil,subprocess
from pathlib import Path
from bent_handoff_inputs import OUT,V4,ROOT,SHELL,CORE
from fixed_core_study import save
from sdf_cfd_mesher_v4.common.authority import file_hash

CLASS='V4BentPrismShellCoreHandoffCharacterized'
NEXT='QualifyV4BranchAwareBentWallDiscretizationAndHandoffRebaseline: explicitly authorize a branch-aware wall/first-layer re-baseline, resolve the multiple-radial-crossing sampling ambiguity, then compare shell and fresh local core handoff under unchanged schedule and gates. Do not resume the 168-tet repair.'

def read(name):return json.loads((OUT/name).read_text())
def table(head,rows):
    return '| '+' | '.join(head)+' |\n| '+' | '.join(['---']*len(head))+' |\n'+''.join('| '+' | '.join(str(v) for v in row)+' |\n' for row in rows)
def fmt(x):return format(x,'.17g') if isinstance(x,float) else str(x)

def seal():
    audit=read('INPUT_AUDIT.json');edge=read('EDGE_REPRODUCTION.json');layers=read('LAYER_STATISTICS.json');maximum=read('MAX_EDGE.json')
    stack=read('STACK_SUMMARY.json');corr=read('CORRELATION.json');patch=read('PATCH_RESULT.json');replay=read('REPLAY.json');col=read('UPPER_TAIL_COLUMN_SUMMARY.json');controls=read('QUALIFIED_CONTROLS.json')
    array_checks={}
    for name in ('PATCH_REPRODUCER.npz','REJECTED_PATCH.npz','CORE_INTERFACE_MAP.npz','EDGE_LINEAGE_ARRAYS.npz','TERMINAL_FIELDS.npz'):
        old=next(r['sha256'] for r in replay['files'] if Path(r['path']).name==name)
        now=file_hash(OUT/name);array_checks[name]=dict(replay_sha256=old,current_sha256=now,equal=old==now)
    assert all(r['equal'] for r in array_checks.values())
    save(OUT/'REPLAY_ARRAYS.json',dict(passed=True,checks=array_checks))
    # This bulk derivative is byte-bound to the unchanged accepted checkpoint.
    # Its unique selected lineage/quality data are retained in compact artifacts.
    # The extraction command reconstructs it for replay; no accepted authority
    # references this new task cache. Do not touch the accepted checkpoint.
    cache=OUT/'CELL_LINEAGE.json';deleted=[]
    if cache.exists():
        resolved=cache.resolve();assert resolved.parent==OUT.resolve()
        cp=json.loads((SHELL/'checkpoint/CURRENT.json').read_text())
        assert file_hash(SHELL/'checkpoint'/cp['payload'])==cp['sha256']
        deleted.append(dict(path=str(resolved),bytes=cache.stat().st_size,sha256=file_hash(cache),
            scientific_value='Duplicate complete cell dictionaries extracted without mutation from sealed terminal checkpoint',
            replacement=str(SHELL/'checkpoint'/cp['payload']),replacement_sha256=cp['sha256'],
            preserved=['EDGE_LINEAGE.json','EDGE_LINEAGE_ARRAYS.npz','UPPER_TAIL_COLUMNS.json','PATCH_REPRODUCER.npz','PATCH_QUALITY.json','bent_handoff_study.py extract'],
            active_authority_reference=False,reason='Regenerable duplicate cache; no unique scientific information lost'))
        save(OUT/'CACHE_CLEANUP.json',dict(deleted=deleted,bytes_deleted=sum(r['bytes'] for r in deleted)))
        assert file_hash(cache)==deleted[0]['sha256'];cache.unlink()
    else:deleted=read('CACHE_CLEANUP.json')['deleted']
    replaycleanup=read('REPLAY_CLEANUP.json');free=shutil.disk_usage(OUT).free
    files=[p for p in OUT.rglob('*') if p.is_file()]
    disk=dict(starting_free_bytes=audit['starting_free_bytes'],precleanup_bytes=0,
        replay_logical_unlinks=replaycleanup['bytes_deleted'],replay_hardlinks_bytes=replay['hardlinked_input_bytes'],
        cache_deleted_bytes=sum(r['bytes'] for r in deleted),
        cleanup_logical_bytes=replaycleanup['bytes_deleted']+sum(r['bytes'] for r in deleted),
        cleanup_unique_payload_bytes=replaycleanup['uniquely_allocated_payload_bytes']+sum(r['bytes'] for r in deleted),
        ending_free_bytes=free,retained_bytes_before_report=sum(p.stat().st_size for p in files),
        task_created_unique_payload_bytes_before_report=sum(p.stat().st_size for p in files)+replaycleanup['uniquely_allocated_payload_bytes']+sum(r['bytes'] for r in deleted),
        peak_physical_disk_consumption='Not measured',crash_dumps='Untouched',
        largest_retained=sorted([(p.stat().st_size,p.name) for p in files],reverse=True)[:10])
    save(OUT/'DISK_FINAL.json',disk)
    events=[json.loads(s) for s in (OUT/'EVENTS.jsonl').read_text().splitlines()]
    ended=[r for r in events if r['stage']=='finished']
    controls_end=next(r for r in events if r['stage']=='upper_tail_quality_complete')
    measured=sum(r['seconds'] for r in ended)+patch['seconds']+controls_end['seconds']+replay['seconds']
    runtime=dict(instrumented_execution_seconds=measured,total_active_scientific_seconds='Not measured',
        accounting='Sum of instrumented main audit, stack refresh, checkpoint extraction recheck, shell patch, controls/column audit and replay. Earlier ad-hoc read-only probes were not all timed.',
        main_audit_seconds=next(r['seconds'] for r in ended if r['mode']=='all'),patch_seconds=patch['seconds'],control_seconds=controls_end['seconds'],replay_seconds=replay['seconds'],
        peak_rss_bytes=max(r['peak_rss'] for r in events),native_solver_invocations=0,maximum_native_solver_duration='Not measured',
        full_shell_seal='Reused sealed authority; no new shell published',local_core_probe='Not measured; shell patch failed quality first')
    save(OUT/'RUNTIME.json',runtime)
    initial=(OUT/'START_STATUS.bin').read_bytes().split(b'\0');current=subprocess.check_output(['git','status','--porcelain=v1','-z'],cwd=ROOT).split(b'\0')
    outside=lambda records:sorted(r for r in records if r and b'research/sdf_cfd_mesher_v4' not in r.replace(b'\\',b'/'))
    assert outside(initial)==outside(current),'UnrelatedDirtyStateChanged'
    v3=subprocess.check_output(['git','status','--porcelain=v1','--','research/sdf_cfd_mesher_v3'],cwd=ROOT)
    before_v3=[r for r in initial if b'research/sdf_cfd_mesher_v3' in r]
    assert before_v3==[r for r in current if b'research/sdf_cfd_mesher_v3' in r]
    assert not subprocess.check_output(['git','diff','--name-only','--','research/sdf_cfd_mesher_v3'],cwd=ROOT)
    save(OUT/'GIT_REVIEW.json',dict(starting_head=audit['starting_head'],unrelated_dirty_entries=len(outside(current)),unrelated_preserved=True,v3_modifications=0,v3_preexisting_status=v3.decode().strip(),staging_scope='Only current V4 task paths'))
    sections=[]
    def add(title,text):sections.append('### '+title+'\n\n'+text.strip()+'\n')
    add('A. Authority verification',f"Starting HEAD: `{audit['starting_head']}`. Branch: `feature/sdf-cfd-mesher-v4-advancing-front`. 725 prior artifact hashes matched. V3 modifications: 0. Unrelated dirty entries: {len(outside(current))}, unchanged.\n\nShell: `5965ee83364ae493ac9bdbc21fe810390f4da7b1799d573ee7bd4fdc36d378a2`. Interface: `db745bee0f0d0751549273e16f89c1e37db9186486e5910925d79c4fd9138c51`. Diagnostic core: `538e0eed8f09c4ee598b540d622e21281832d303b8fcf7027a54a19498d0f411`.")
    add('B. Existing shell claim and its scope',"The unchanged shell contains 155,464 prisms, 76 pyramids and 64 tetrahedra: 155,604 cells. Interface: 4,098 vertices, 8,192 triangles, 12,288 edges. All 8,192 columns are terminal; 8,008 have last-prism layer 19 and 184 have last-prism layer 18. Layer 20 remains absent. The old seal proves its discrete shell quality, incidence, degree/filling and continuous certificate obligations. It does not prove suitable tangential sampling for a tet core. No old gate violation is claimed.\n\nThe preserved binary64 targets are 0.014511348470640867 m at layer 18, 0.017048444695105157 m at layer 19, and 0.020000000131704564 m requested at layer 20. h1=0.000166527069 m; growth=1.163359674. No schedule value changed.")
    add('C. Full prism-layer edge audit',table(['Layer','min m','median m','p90 m','p95 m','p99 m','p99.5 m','p99.9 m','max m'],[[r['layer']]+[fmt(r['edge'][k]) for k in ('min','median','p90','p95','p99','p99.5','p99.9','max')] for r in layers])+"\nLayer 0 is wall. Layers 1–18 are complete committed source-triangle tops. Layer 19 is the actual mixed terminal surface, including 44 exposed layer-18 prism faces; unused layer-19 coordinate rows are excluded.")
    add('D. Full prism-layer triangle audit',table(['Layer','max area m2','min angle deg','max angle deg','max edge ratio'],[[r['layer']]+[fmt(r['triangles'][k][side]) for k,side in [('area','max'),('minimum_angle','min'),('maximum_angle','max'),('edge_ratio','max')]] for r in layers])+"\nFull distributions, circumradius, inradius and R/(2r) are in LAYER_STATISTICS.json. These are descriptive shape measures, not new gates.")
    add('E. Maximum 29.053 mm edge forensics',f"The maximum reproduces exactly: {fmt(edge['percentiles']['max'])} m. Terminal indices: {maximum['vertices']}; keys: {maximum['vertex_keys']}. Endpoints: {maximum['endpoint_coordinates']} m. Source wall edge: {maximum['source_vertices']}, wall-edge index {maximum['source_wall_edge']}. Wall endpoints: {maximum['wall_endpoint_coordinates']} m. Wall length: {fmt(maximum['wall_length'])} m. Source columns {maximum['source_columns']}; terminal triangles {maximum['faces']}; both owners are layer-18 prisms.\n\n"+table(['Layer','same source edge length m'],[[i,fmt(v)] for i,v in enumerate(maximum['length_by_layer'])])+"\nThe layer-19 entry is an unused source-coordinate diagnostic (0.026300092964155673 m), not an accepted edge. The actual terminal edge remains the layer-18 edge. It first occurs at the wall, with no source-edge topology change. Remeshing leaves these stopped columns exposed; it does not create their edge.\n\n"+f"Endpoint source rays differ by {fmt(read('WALL_RAY_FORENSICS.json')['direction_separation_degrees'])} degrees. The existing wall triangles share the edge, so there is no accidental index connection. A sampled projected surface path has length {fmt(maximum['projected_chord_path_polyline_length'])} m and target residual {fmt(maximum['projected_path_residual'])} m. This is an available path, not a shortest-geodesic proof. Chord phi ranges from {fmt(maximum['terminal_chord_phi']['min'])} to {fmt(maximum['terminal_chord_phi']['max'])} m, versus its endpoint target 0.014511348470640867 m. Planar interpolation does not stay on the analytic target surface.")
    add('F. Edge lineage through the stack',f"Counts: {stack['lineage_counts']}. Transition-created: 0; remesh-created source pairs: 0; unresolved: 0. The 140 mixed edges join different endpoint layers at layer 19 but retain an existing wall source pair. 'Inherited with stretch' means strictly larger terminal than wall length, not violation of a numeric gate.\n\nAll 14 p99.9-tail edges already existed at the wall and became shorter; their terminal/wall ratios range {fmt(stack['tails']['0.999']['terminal_over_wall']['min'])}–{fmt(stack['tails']['0.999']['terminal_over_wall']['max'])}. The p99 tail contains {stack['tails']['0.99']['count']} edges including ties; {stack['tails']['0.99']['remesh_associated']} touch stopped/transition regions. EDGE_LINEAGE.json and EDGE_LINEAGE_ARRAYS.npz retain every edge and all source-layer lengths.")
    add('G. Terminal owner and transition analysis',table(['Owner','faces','median longest edge m','p99 longest edge m','maximum edge m','maximum area m2'],[[k,v['faces'],fmt(v['longest_edge']['median']),fmt(v['longest_edge']['p99']),fmt(v['longest_edge']['max']),fmt(v['area']['max'])] for k,v in stack['owner'].items()])+"\nPrism owners include 8,008 layer-19 faces and 44 exposed layer-18 faces. The 76 pyramid and 64 tet faces account for the other 140 early-stopped-column transitions. The largest edge is prism-owned; the largest area is tet-owned. Transition topology amplifies area/angle extremes locally, but does not originate the inherited long-edge tail.")
    add('H. Local remaining core depth',"Method: evaluate the authoritative bent SDF branch's nearest clamped arc point and take Euclidean distance to that medial curve. This is one-sided inward remaining capacity, not a global or two-sided thickness. Source identity: `"+stack['depth']['binding']['source_identity']+"`.\n\n"+table(['Sample','min m','median m','max m'],[[k]+[fmt(v[s]) for s in ('min','median','max')] for k,v in stack['depth'].items() if k!='binding']))
    er=stack['max_edge_over_depth']
    add('I. Interface-size versus core-depth diagnostics',f"Edge length / midpoint depth: median {fmt(stack['edge_over_depth']['median'])}, p99 {fmt(stack['edge_over_depth']['p99'])}, maximum {fmt(er['ratio'])}. Maximum at terminal edge {er['edge']}, midpoint {er['midpoint']} m; length {fmt(er['length'])} m, depth {fmt(er['depth'])} m; mixed layer-18/19 edge, shell-tet owners. Triangle circumradius / centroid depth: median {fmt(stack['radius_over_depth']['median'])}, maximum {fmt(stack['radius_over_depth']['max'])}. Face-mapped core correlations use longest face edge / face-centroid depth, a different sample convention. No ratio is an acceptance threshold.")
    add('J. Mapping of 168 determinant failures',"The unchanged retained core still has 14,173 tets, 453 interior vertices, 168 determinant failures in 146 components; largest component 3. All other frozen metrics pass. 19 failures have direct interface faces; 149 do not. Nearest-surface queries examine every terminal triangle, not nearest centroids. Every failing tet and nearest edge/face is recorded.\n\n"+table(['Nearest shell owner','all core cells','failures'],[[k,v['population'],v['failures']] for k,v in corr['owner'].items()])+f"\n{corr['transition']['failures']} failures map to lower-layer/transition neighborhoods out of {corr['transition']['population']} total cells in those neighborhoods. Direct interface failure owners: 4 prism, 7 pyramid, 8 shell tet. These differ from nearest-face counts above.")
    add('K. Passing-core controls',"168 controls are selected without replacement by nearest cell centre within the same nearest-owner type and direct-interface-incidence stratum.\n\n"+table(['Descriptor','failing median','matched passing median','failure larger /168'],[[k,fmt(v['failing']['median']),fmt(v['matched_passing']['median']),v['paired_failure_larger']] for k,v in corr['comparison'].items()])+"\nAbove the terminal-face p90 longest-edge cutoff, 78/1,868 mapped core cells fail (4.1756%); outside it, 90/12,305 fail (0.7314%). Above the core-population p90 edge/depth descriptor, 68/1,421 fail (4.7854%), versus 100/12,752 (0.7842%). These tail cutoffs describe populations only. Matched-neighborhood medians are similar: neither length alone nor one correlation establishes causality. The retained core also reflects prior optimization and is not a randomized experiment.")
    add('L. Qualified geometry controls',table(['Control','median edge m','max edge m','median minimum triangle angle deg','preserved core min determinant'],[[k,fmt(v['audit']['edge_distribution']['median']),fmt(v['audit']['edge_distribution']['max']),fmt(v['triangle']['minimum_angle']['median']),fmt((v['quality'].get('core') or v['quality'])['minimum']['determinant'])] for k,v in controls.items()])+"\nCapsule: bounded exterior core, 31,366 tets and 195,206 complete cells. SF2: preserved exterior wing/support core, 1,597,714 tets. Both preserved authorities pass; neither was regenerated. Their exterior domains do not have the bent cavity's inward medial-depth definition. Comparable edge/depth distributions: Not measured. SF2's passing 39.309 mm maximum rules out using bent's 29 mm value as a universal edge-length gate.")
    ray=read('WALL_RAY_FORENSICS.json')
    add('M. Root-cause diagnosis',"The geometric sampling defect starts at the wall. `geometry_family_authority.radial_wall` maps a uniform octahedral direction mesh through one radial bisection. It checks the initial bracket but does not establish a unique crossing on each ray. Between the maximum edge's adjacent rays, a midpoint ray has three sign-changing source intersections at radial distances "+', '.join(fmt(v) for v in ray['records'][1]['bracketed_roots'])+" m. Alternating interior/exterior witnesses exceed source error bounds. Thus a single radial chart crosses a non-star-shaped region and produces a large sampling jump. This is measured geometry evidence; no global root-completeness claim is made.\n\nPrism advancement does not cause the longest-edge tail: that edge shortens by "+fmt(100*maximum['length_reduction_from_wall'])+"%. It does worsen tangential triangle shape: minimum angle goes from 3.606871009450277 degrees at wall to 1.1726868859878128 degrees terminal; maximum angle grows from 147.98768328254042 to 172.6551133588739 degrees. Termination exposes part of this inherited coarse stack and adds mixed-layer geometry.\n\nSupported causal statement: the radial wall sampling produces the inherited terminal discretization jump. Large-face/core-depth neighborhoods are associated with failures. It is not proved that this jump causes all 168 failures, or that every fixed-interface core is infeasible.")
    add('N. Core-handoff readiness decision',"**V4BentTerminalInterfaceCoreReadinessNotEstablished.** `CoreReady` requires direct passing, identity-bound core-handoff evidence. `ReadinessFailed` would require an established handoff obstruction under the fixed contract; failure of a finite search alone does not prove it. Current evidence establishes neither a passing core nor universal infeasibility. ShellQualified remains valid. The handoff sampling defect and missing admission contract are characterized.")
    add('O. Shell-side repair design',"One generic shallow candidate bisects the longest same-target terminal edge, projects the midpoint through the authoritative SDF normal, and replaces its complete two-prism edge star. Parent centroids serve as interior cone points. Unchanged quadrilateral attachment faces remain pyramid bases; both sides use identical triangulation of changed shared faces. No hanging nodes, wall edits or first-layer edits are permitted. No core coordinates or topology are repaired.")
    add('P. Shell-side repair results',f"Rejected. Removed two layer-18 prism candidates; inserted one terminal target point and two interior shell points. Replacement: 12 tetrahedra and 4 pyramids. Trial total: 155,618 shell cells (155,462 prisms, 80 pyramids, 76 tets). 155,602 original cells are unchanged. Topology/ownership and vertex links pass. Wall coordinates/topology and first-layer coordinates/topology remain exact. Target residual {fmt(patch['target_residual'])} m, within source error {fmt(patch['source_error_bound'])} m.\n\n12 cell-quality rows fail determinant; minimum {fmt(patch['minimum_determinant'])}. Guarded minimum weight {fmt(patch['minimum_weight'])}; ratio {fmt(patch['minimum_ratio'])}; maximum skew {fmt(patch['maximum_skew'])}; aspect {fmt(patch['maximum_aspect'])}. All local exact volume/Jacobian checks pass. No candidate publishes. Runtime {fmt(patch['seconds'])} s. The task stops shell repair at the requested hard-gate failure condition; no deeper search is claimed exhausted.")
    add('Q. Local core-handoff before/after evidence',"Not measured. The shallow shell patch fails its own determinant gate, so no valid repaired boundary exists for the required fresh local tet-fill comparison. Before/after core determinant counts/minima, weight failures and ratio failures: Not measured. No claim of handoff improvement is made. The retained 168-failure core remains byte-identical.")
    add('R. Shell quality and certification',f"Existing upper-tail population: {col['prisms']} prisms in {col['columns']} columns. All exact volumes/Jacobians and shell metrics pass: determinant min {fmt(col['minimum_determinant'])}; weight min {fmt(col['minimum_weight'])}; ratio min {fmt(col['minimum_ratio'])}; skew max {fmt(col['maximum_skew'])}; aspect max {fmt(col['maximum_aspect'])}. Column non-orthogonality: Not measured.\n\nOriginal independent seal reused unchanged: 155,604 degree-one witnesses; exact cell/boundary volume equality; 13,651,424 certificate relations; missing/duplicate/forbidden/unresolved = 0/0/0/0. No new full shell seal is needed for an unchanged authority. Rejected-patch complete-neighbor core closure, global filling and continuous certificate: Not measured; early rejection prevents any acceptance claim.")
    add('S. Future pre-core admission stage',"`core_handoff_audit.pre_core_audit` binds exact array identities, measures terminal edges/triangles, exposes owner/layer/source regions, and records branch-bound depth when supported. `broader_geometry_core.run` saves PRE_CORE_HANDOFF.json before invoking Gmsh. Missing or inapplicable depth is explicit. Stable diagnostic rankings localize possible probes. There is no numeric geometric handoff gate. Direct local feasibility can qualify a tested patch only; complete CoreHandoffQualified still requires complete core/interface quality, filling and certificate evidence.")
    add('T. Qualification-contract update',"CORE_HANDOFF_CONTRACT.md separates ShellQualified from CoreHandoffQualified. Historical reports are untouched. Shell/source/first-layer identities remain unchanged. The failed upper-shell experiment has no publisher and cannot grant readiness. The generic wall-chart ambiguity is exposed; changing that historical source discretization needs a new, explicitly authorized wall/first-layer authority.")
    add('U. Determinism',"20 scientific replay checks pass exactly: 15 record/map comparisons plus 5 binary array comparisons. These bind full layer statistics, edge lineage, maximum-edge record, interface maps, control maps, core quality, original/failed-patch local quality, VTK maps, inserted coordinates and replacement connectivity. Patch runtime is excluded from scientific identity. Accepted repaired shell/core replay: Not measured; none exists.")
    add('V. Runtime and memory',table(['Stage','seconds'],[['stack and all-core correlation',fmt(runtime['main_audit_seconds'])],['rejected shell patch',fmt(patch['seconds'])],['source/control/2,780-prism audit',fmt(runtime['control_seconds'])],['independent deterministic replay',fmt(replay['seconds'])],['all instrumented execution including refresh/extraction',fmt(measured)]])+f"\nTotal active scientific execution including earlier untimed ad-hoc probes: Not measured. Peak recorded RSS {runtime['peak_rss_bytes']} bytes, during sealed checkpoint extraction. Main audit peak 538,136,576 bytes; correlation retained about 82.6 MB; original patch peak 733,179,904 bytes. Native mesher invocations: 0; maximum solver duration: Not measured. Core queries emit progress every 1,024 cells. No opaque stage approached 120 s.")
    add('W. Disk management',f"Starting free bytes {disk['starting_free_bytes']}; V4 result-tree logical bytes {audit['v4_result_bytes']}. 10 inaccessible link entries are recorded. Pre-run cleanup 0 bytes. Accepted authorities and old dumps untouched. Replay scratch removal: {disk['replay_logical_unlinks']} logical bytes, including {disk['replay_hardlinks_bytes']} bytes of hardlinked inputs (not physically freed). Regenerable cell-cache removal: {disk['cache_deleted_bytes']} bytes. Total unique task payload removed: {disk['cleanup_unique_payload_bytes']} bytes. Ending observed free bytes {free}. Retained task payload before report/manifest: {disk['retained_bytes_before_report']} bytes. Unique created task payload before report/manifest: {disk['task_created_unique_payload_bytes_before_report']} bytes. Peak physical task disk allocation: Not measured.\n\nRetained: compact geometry, source/schedule binding, all lineage arrays/maps, 168 failure and matched control maps, local quality/reproducer, replay records, VTK spatial fields, tests and cleanup hashes. Deleted only byte-verified replay duplicates and a checkpoint-regenerable cell dictionary. Paths, hashes, replacements and reasons are in cleanup manifests.")
    add('X. Tests',"96 distinct tests pass. Initial focused run: 94 passed in 6.34 s (handoff audit, fast core handoff, terminal capacity, mixed front, local termination topology and terminal-cap conformity). Two additional tests cover the multiple-crossing wall reproducer and audit-before-native-work integration. Final affected audit/handoff run: 24 passed in 0.89 s. Earlier affected recheck: 22 passed in 0.76 s. No failed tests. Coverage includes measurement, lineage classes, owner/depth binding, true nearest-triangle mapping, source projection, conformity, wall/first-layer protection, no promotion from shell success, deterministic diagnostics and rejection/publication separation. Repair-stage complete continuous certification and fresh local core comparison were not reached and are not represented as tested scientific successes.")
    add('Y. Classification',f"**{CLASS}.** The inherited wall sampling discontinuity and upper-shell shape degradation are established. A conformal shallow repair fails frozen shell determinant gates. No repair or core-handoff qualification is claimed. No numeric threshold or universal fixed-interface infeasibility claim is supported. Terminal discretization is implicated as a risk and geometry sampling issue; its causal share of the 168 core failures remains unresolved.")
    add('Z. Recommended next task',NEXT)
    report='## Decision question\n\nDoes the qualified bent prism shell provide a terminal interface with suitable discretization for tetrahedral core generation under the frozen V4 core gates?\n\n'+'\n'.join(sections)
    (OUT/'report.md').write_text(report,encoding='utf8')
    paths=[p for p in OUT.rglob('*') if p.is_file() and p.name not in ('AUTHORITY.json','SHA256SUMS.json')]
    tools=['bent_handoff_inputs.py','bent_handoff_study.py','bent_handoff_controls.py','bent_handoff_patch_trial.py','bent_handoff_replay.py','bent_handoff_finalize.py','core_handoff_audit.py','upper_shell_handoff_patch.py','broader_geometry_core.py']
    sources=[V4/'tools'/n for n in tools]+[V4/'tests/test_core_handoff_audit.py',V4/'CORE_HANDOFF_CONTRACT.md',V4/'README.md']
    authority=dict(schema='V4BentPrismShellCoreHandoff/1',classification=CLASS,starting_head=audit['starting_head'],shell_identity='5965ee83364ae493ac9bdbc21fe810390f4da7b1799d573ee7bd4fdc36d378a2',
        interface_identity='db745bee0f0d0751549273e16f89c1e37db9186486e5910925d79c4fd9138c51',core_identity=corr['core']['identity'],
        shell_claim='ShellQualified; preserved',handoff_claim='V4BentTerminalInterfaceCoreReadinessNotEstablished',numeric_gate=None,
        shell_repaired=False,core_repaired=False,layer20_attempted=False,v3_modifications=0,
        report_sha256=file_hash(OUT/'report.md'),artifacts=[dict(path=str(p.relative_to(OUT)),bytes=p.stat().st_size,sha256=file_hash(p)) for p in sorted(paths)],
        implementations=[dict(path=str(p.relative_to(V4)),sha256=file_hash(p)) for p in sources],recommended_next_task=NEXT)
    save(OUT/'AUTHORITY.json',authority)
    save(OUT/'SHA256SUMS.json',{'report.md':file_hash(OUT/'report.md'),'AUTHORITY.json':file_hash(OUT/'AUTHORITY.json')})
    print(json.dumps(dict(classification=CLASS,hashes=read('SHA256SUMS.json'),disk=disk,runtime=runtime),indent=2))

